  .sort((a, b) => ((b.data && b.data.chiave) || '').localeCompare((a.data && a.data.chiave) || '') || b.riga - a.riga)
  .slice(0, quanti)
  .map(({ data, riga, ...x }) => ({ ...x, data_ora: data ? data.chiave : '' }));
// ── fine funzioni di servizio ──
const cfg = $('Config').first().json;
const MAX = Number(cfg.MAX_PER_GIRO) || 5;
const lavori = $('Righe da lavorare').all().map((i) => i.json);
const clienti = {};
for (const i of $('Leggi i clienti').all()) { const r = i.json || {}; if (testo(r.cliente)) clienti[testo(r.cliente).toLowerCase()] = schedaCliente(r); }
// La scheda Esempi (correzioni del team e post migliori): se manca, qui arriva altro e non si tiene niente.
const righeEsempi = $input.all().map((i) => i.json || {});
// Il «marcatore» dice chi ha prenotato la riga e quando: serve per scoprire le righe rimaste a metà.
const marcatore = `testi ${$execution.id} ${new Date().toISOString()}`;

const uscita = [];
const errori = [];       // righe che passano a «errore»: si avvisa subito, una volta sola
const senzaId = [];      // righe senza id unico: non si possono segnare, si ricordano una volta al giorno
const daScrivere = [];
for (const l of lavori) {
  if (l.lavoro === 'segnala') { senzaId.push(l.problema); continue; }
  if (l.lavoro === 'errore') { uscita.push({ azione: 'errore', id: l.id, errore: l.errore }); errori.push(`${l.id}: ${l.errore}`); continue; }
  if (l.lavoro === 'storia') {
    const nota = 'storia: non ha didascalia, nessun testo da scrivere';
    uscita.push({ azione: 'storia', id: l.id, note: l.note_attuali.includes(nota) ? l.note_attuali : [l.note_attuali, nota].filter(Boolean).join(' | ') });
    continue;
  }
  const cliente = clienti[l.cliente.toLowerCase()];
  if (!cliente) {
    const errore = `il cliente «${l.cliente}» non c'è nella scheda Clienti`;
    uscita.push({ azione: 'errore', id: l.id, errore });
    errori.push(`${l.id}: ${errore}`);
    continue;
  }
  if (!cliente.attivo) continue; // cliente spento: la riga aspetta in «da_scrivere»
  daScrivere.push({ ...l, cliente_scheda: cliente });
}
// Le più vicine alla data di pubblicazione prima; senza data in fondo.
daScrivere.sort((a, b) => ((a.data && a.data.chiave) || '9999').localeCompare((b.data && b.data.chiave) || '9999'));
for (const l of daScrivere.slice(0, MAX)) {
  uscita.push({ azione: 'prenota', id: l.id, marcatore, cliente_scheda: l.cliente_scheda,
    esempi: esempiDelCliente(righeEsempi, l.cliente_scheda.cliente, ['correzione', 'migliori_post'], 8) });
}

// Il messaggio per il team: gli errori subito; le righe senza id solo nel giro tra le 9:00 e le 9:09,
// così il promemoria arriva una volta al giorno e non ogni 10 minuti.
const ora = oggiRoma();
const daRicordare = ora.ore === 9 && ora.minuti < 10 ? senzaId : [];
const elenco = [...errori, ...daRicordare];
if (elenco.length) {
  uscita.push({ azione: 'avvisa', messaggio_telegram: unisci([
    '⚠️ *Scrittura dei testi: righe da sistemare*',
    ...elenco.slice(0, 30).map((s) => '• ' + md(s)),
    elenco.length > 30 ? `…e altre ${elenco.length - 30}.` : null,
    errori.length ? `Le righe in «errore» si riprovano rimettendo lo stato «${md('da_scrivere')}».` : null,
    daRicordare.length ? 'Alle righe senza id unico va dato un id diverso dalle altre, poi si lavorano da sole.' : null,
  ]) });
}
return uscita.map((u) => ({ json: u }));

