  .sort((a, b) => ((b.data && b.data.chiave) || '').localeCompare((a.data && a.data.chiave) || '') || b.riga - a.riga)
  .slice(0, quanti)
  .map(({ data, riga, ...x }) => ({ ...x, data_ora: data ? data.chiave : '' }));
// ── fine funzioni di servizio ──
const prenotate = $('Prepara il giro').all().map((i) => i.json).filter((x) => x.azione === 'prenota');
if (!prenotate.length) return [];
const marcatore = prenotate[0].marcatore;
