for (const p of prenotate) perId[p.id] = p;
const uscita = [];
for (const i of $input.all()) {
  const r = i.json || {};
  const p = perId[testo(r.id)];
  if (!p || testo(r.esecuzione) !== marcatore || testo(r.stato).toLowerCase() !== 'in_scrittura') continue;
  const { row_number, ...riga } = r;
  uscita.push({ json: { fase: 'scrivi', id: testo(r.id), marcatore, riga, cliente: p.cliente_scheda, esempi: p.esempi || [] } });
}
return uscita;

